I found one root cause: `ts-station-service` has slow database calls. Its effect travels up through the callers to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, span_name, attr_span_kind kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-station-service' AND attr_span_kind='Client' GROUP BY 2,3 UNION ALL SELECT 'norm', span_name, attr_span_kind, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-station-service' AND attr_span_kind='Client' GROUP BY 2,3", "claim": "Station's DB client span 'SELECT ts.station' p95 rose from 0.3ms to 280ms while its own controller and resource metrics stayed flat."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name IN ('ts-station-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind='Server' GROUP BY 2,3 UNION ALL SELECT 'norm', service_name, attr_span_kind, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name IN ('ts-station-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind='Server' GROUP BY 2,3", "claim": "Station server p95 went 2.6ms to 421ms; no other DB client span in any service slowed, so the fault is station-specific."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),2) avgv, round(max(value),2) maxv FROM abnormal_metrics WHERE service_name='ts-station-service' AND metric IN ('container.cpu.usage','container.memory.working_set','k8s.pod.cpu.usage') GROUP BY 1", "claim": "Station container CPU and memory stayed at normal levels during the slow period."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-station-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-basic-service' AND s.service_name='ts-station-service' GROUP BY 1,2", "claim": "Basic-service calls to station see server p95 of about 419ms in the abnormal period."}]},
    {"from": "ts-basic-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND s.service_name='ts-basic-service' GROUP BY 1,2", "claim": "Travel2 calls to basic-service see server p95 of about 428ms, inherited from station."}]},
    {"from": "ts-basic-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND s.service_name='ts-basic-service' GROUP BY 1,2", "claim": "Travel-service calls to basic-service see server p95 of about 221ms in the abnormal period."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Route-plan calls to travel2 see server p95 of about 427ms in the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Route-plan calls to travel-service see server p95 of about 222ms in the abnormal period."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan calls to route-plan see server p95 of about 460ms in the abnormal period."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1", "claim": "Dashboard travelPlan cheapest and quickest endpoints rose to about 460-520ms p95, from about 40ms."}]},
    {"from": "ts-station-service", "to": "ts-admin-basic-info-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(s.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-admin-basic-info-service' AND s.service_name='ts-station-service' GROUP BY 1,2", "claim": "Admin-basic-info calls to station see server p95 of about 437ms in the abnormal period."}]},
    {"from": "ts-admin-basic-info-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name = 'GET /api/v1/adminbasicservice/adminbasic/stations' GROUP BY 1", "claim": "Dashboard GET adminbasic/stations p95 rose to about 1594ms, from about 5ms in normal period."}]}
  ]
}
